def register(email, mailer):
    if "@" not in email:
        raise ValueError("invalid email")
    mailer.send(email, "Добро пожаловать!")
    return True

def get_with_retry(client, path, attempts=3):
    for _ in range(attempts):
        resp = client.get(path)
        if resp.status_code < 500:
            return resp
    return resp
